import {QUESTIONS,SUBJECTS,ROUNDS,SOURCES} from './questions.js';
import {STUDY_CARDS,STUDY_SOURCES} from './study-guide.js';
import {SUMMARY_NOTES,NOTE_CHAPTERS} from './summary-notes.js';
import {EASY_NOTES,renderEasyNote} from './easy-notes.js';
import {NOTE_ILLUSTRATIONS} from './note-illustrations.js';
import {CHAPTER_GUIDES} from './note-depth.js';
import {BY_ID,STORAGE_KEY,initialState,shuffled,examQuestions,createSession,remainingSeconds,isDeferredMode,checkSessionAnswer,finishSession,validateState,stats,daysLeft} from './core.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roundRange=()=>`${ROUNDS.at(-1).number}~${ROUNDS[0].number}회`;
const modeLabel=mode=>isDeferredMode(mode)?'한 번에 채점':'문항별 해설';
const paths={
  home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',
  book:'<path d="M12 6c-3-2-6-2-9-1v15c3-1 6-1 9 1m0-15c3-2 6-2 9-1v15c-3-1-6-1-9 1V6Z"/>',
  bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',
  chart:'<path d="M4 3v18h17M9 16v-5m5 5V7m5 9V4"/>',
  settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',
  back:'<path d="m15 5-7 7 7 7"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  x:'<path d="m6 6 12 12M18 6 6 18"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
  layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5"/>',
  grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  refresh:'<path d="M20 7V3l-3 3a9 9 0 1 0 3 9M20 7h-4"/>',
  leaf:'<path d="M20 3c-9-1-16 2-16 10 0 4 4 6 7 4 7-3 9-7 9-14ZM4 21l11-11"/>',
  search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
  spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4L12 3Z"/>',
};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]??paths.book}</svg>`;
const art=`<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 260 220" fill="none"><circle cx="130" cy="117" r="90" fill="#D8E3FF"/><path d="m49 85 97-24 42 130-97 24Z" fill="#ADC0F0"/><rect x="74" y="33" width="132" height="167" rx="13" transform="rotate(8 74 33)" fill="#304F9D"/><rect x="72" y="29" width="126" height="164" rx="11" transform="rotate(8 72 29)" fill="#FFFFFF"/><path d="m176 44-16-2-5 34 9-5 7 7 5-34Z" fill="#5679C4"/><path d="m89 64 53 7m-56 13 63 9m-66 12 63 9" stroke="#CBD6EE" stroke-width="5" stroke-linecap="round"/><circle cx="122" cy="144" r="27" fill="#E0E9FF"/><path d="m107 143 10 11 20-20" stroke="#4063AF" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/><path d="m51 59 4-10 4 10 10 4-10 4-4 10-4-10-10-4 10-4Z" fill="#8CA8EA"/><path d="M223 125c-11-2-19 1-22 11 11 4 21 0 22-11Z" fill="#7696D7"/><path d="M231 144c-13-1-21 3-23 12 11 2 21-1 23-12Z" fill="#ADC3EF"/><path d="m201 166 12-37" stroke="#5875B4" stroke-width="2"/><circle cx="61" cy="153" r="5" fill="#9AB2E5"/><circle cx="212" cy="73" r="3" fill="#9AB2E5"/></svg></div>`;
let state,storageWarning=false;
try{const raw=localStorage.getItem(STORAGE_KEY);state=raw?validateState(JSON.parse(raw)):initialState();}catch{state=initialState();storageWarning=true;}
let view=location.hash.slice(1)||'home',filter='all',reviewFilter='wrong',subjectFilter=0,search='',result=null,offlineReady=false,installPrompt=null,swRegistration=null;
const views=['home','practice','review','progress','settings','concepts','quiz','result'];
if(!views.includes(view)||view==='result'||view==='quiz'&&!state.active)view='home';
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{toast('저장 공간에 접근할 수 없습니다. 설정에서 기록을 백업해 주세요.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function go(next){view=next;history.replaceState(null,'','#'+next);render();renderBankList();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function dialog(title,body,actions=''){const el=$('#dialog');el.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="닫기">${icon('x')}</button></div>${body}${actions?`<div class="settings-actions">${actions}</div>`:''}`;el.showModal();}
function closeDialog(){$('#dialog').close();}
function confirmDialog(title,body,action,label='계속하기'){dialog(title,`<p>${body}</p>`,`<button class="secondary" data-action="close-dialog">취소</button><button class="primary" data-action="${action}">${label}</button>`);}
const bookmarkBtn=q=>`<button class="icon-btn ${state.bookmarks.includes(q.id)?'on':''}" data-action="bookmark" data-id="${q.id}" aria-pressed="${state.bookmarks.includes(q.id)}" aria-label="${state.bookmarks.includes(q.id)?'북마크 해제':'북마크 저장'}">${icon('bookmark',19)}</button>`;
const navItems=[['home','home','학습 홈'],['practice','book','기출 연습'],['concepts','spark','요약·암기'],['review','bookmark','오답 노트'],['progress','chart','내 기록'],['settings','settings','설정']];
function nav(mobile=false){return `<nav class="${mobile?'mobile-nav':'nav'}" aria-label="${mobile?'모바일 메뉴':'주 메뉴'}">${navItems.filter(([v])=>!mobile||v!=='progress').map(([v,i,t])=>`<button data-action="navigate" data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i,mobile?21:17)}<span>${t}</span></button>`).join('')}</nav>`;}
function render(){
  document.documentElement.dataset.font=state.fontSize;
  $('#app').innerHTML=`<div class="shell"><header class="topbar"><a href="#home" class="brand" data-action="navigate" data-view="home"><span class="brand-mark">${icon('book',22)}</span><span class="brand-name">ADsP<span>pocket</span></span></a>${nav()}<div class="header-status ${offlineReady?'':'pending'}"><span class="dot"></span><span>${offlineReady?'오프라인 준비 완료':'개인 학습실'}</span></div></header><main id="main" class="content" tabindex="-1">${content()}</main><footer class="footer"><span>작은 풀이가 모여, 확실한 자신감으로.</span><button data-action="sources">문항 안내 · 출처</button></footer></div>${nav(true)}`;
  if(view==='practice'||view==='review'){const input=$('#search');input?.addEventListener('input',e=>{search=e.target.value;renderBankList();});}
  if(view==='concepts'){$('#study-search')?.addEventListener('input',e=>{studySearch=e.target.value;renderStudyList();});}
  updateTimer();
}
function content(){return ({home:homePage,practice:practicePage,review:reviewPage,progress:progressPage,settings:settingsPage,concepts:conceptPage,quiz:quizPage,result:resultPage}[view]??homePage)();}
function homePage(){
  const s=stats(state),left=daysLeft(state.examDate);
  const target=left>0?`D-${left}`:left===0?'D-DAY':`D+${Math.abs(left)}`;
  return `<div class="greeting-row"><div><div class="eyebrow">MY LITTLE STUDY ROOM</div><h1>오늘도, 한 걸음 더.</h1></div><button class="date-pill" data-action="navigate" data-view="settings">나의 시험 <strong>${target}</strong></button></div>${state.active?`<div class="resume">${icon('clock',18)}<span>${esc(state.active.title)} · ${state.active.index+1}/${state.active.ids.length}</span><button data-action="resume">이어서 풀기 →</button></div>`:''}<section class="hero"><div><div class="eyebrow"><span class="dot"></span> 하루 10문제, 나의 합격 습관</div><h1>조금씩 풀고,<br>확실하게 합격.</h1><p>최근 출제 주제로 감각을 깨우세요.<br>오늘의 10문제부터 가볍게 시작해요.</p><button class="primary" data-action="quick">오늘의 10문제 ${icon('arrow',17)}</button></div>${art}</section><div class="stats"><div class="stat"><div><span class="stat-label">나의 학습 진도</span><strong>${s.unique}<span>/ ${QUESTIONS.length}</span></strong></div><span class="stat-icon">${icon('book',19)}</span></div><div class="stat"><div><span class="stat-label">누적 정답률</span><strong>${s.accuracy??'—'}<span>${s.accuracy===null?'아직 시작 전':'%'}</span></strong></div><span class="stat-icon">${icon('check',19)}</span></div><div class="stat"><div><span class="stat-label">복습할 오답</span><strong>${s.wrong}<span>문제</span></strong></div><span class="stat-icon">${icon('refresh',18)}</span></div></div><div class="two-col"><section><div class="section-head"><h2>회차별 기출 주제</h2><button class="text-btn" data-action="navigate" data-view="practice">모두 보기 ${icon('chevron',13)}</button></div><div class="rounds">${ROUNDS.slice(0,3).map(roundCard).join('')}</div><button class="secondary full round-more" data-action="navigate" data-view="practice">${roundRange()} 모두 보기 ${icon('arrow',16)}</button><p class="note">회차마다 주제 재구성과 보충을 합쳐 50문제입니다.<br>문항에 보충 여부와 출처를 표시하며 실제 원문·순서와 다릅니다.</p></section><aside><section class="exam-card"><div class="eyebrow">READY FOR THE REAL THING?</div><h2>실전처럼,<br> 한 번에 50문제.</h2><p>시간 관리부터 과락 확인까지.</p><div class="exam-meta"><span>${icon('clock',15)} 90분</span><span>${icon('layers',15)} 10 · 10 · 30</span></div><button class="primary" data-action="exam-intro">모의고사 시작 ${icon('arrow',16)}</button></section><button class="install-card" data-action="install">${icon('download',22)}<div><h3>내 폰에 학습실 담기</h3><p>홈 화면에 설치하고 오프라인으로.</p></div></button></aside></div><section class="subjects"><div class="section-head"><h2>과목별로 차근차근</h2><button class="text-btn" data-action="navigate" data-view="concepts">요약·암기 ${icon('chevron',13)}</button></div><div class="subject-grid">${SUBJECTS.map((title,i)=>subjectCard(title,i+1)).join('')}</div></section>`;
}
function roundCard(r){const qs=QUESTIONS.filter(q=>q.round===r.number),done=qs.filter(q=>state.attempts[q.id]).length,supplement=qs.filter(q=>q.supplement).length;return `<button class="round-card" data-action="round" data-round="${r.number}"><span class="round-number">${r.number}</span><div class="round-info"><div class="round-title"><h3>${r.number}회 출제 주제</h3>${r.badge?`<span class="badge">${r.badge}</span>`:''}</div><p>${r.date} · ${qs.length}문제<span class="round-coverage">주제 ${qs.length-supplement} · 보충 ${supplement}</span></p><div class="progress-line"><span style="width:${done/qs.length*100}%"></span></div></div><span class="round-arrow">${icon('chevron',15)}</span></button>`;}
function subjectCard(title,i){const qs=QUESTIONS.filter(q=>q.subject===i),done=qs.filter(q=>state.attempts[q.id]).length;return `<button class="subject-card" data-action="subject" data-subject="${i}"><small>SUBJECT 0${i}</small><h3><span class="subject-icon">${icon(['layers','spark','chart'][i-1],17)}</span>${title}</h3><p>${done} / ${qs.length}문제 학습</p><div class="progress-line"><span style="width:${done/qs.length*100}%"></span></div></button>`;}
function pageHead(title,description){return `<div class="page-head"><h1>${title}</h1><p>${description}</p></div>`;}
function roundCatalog(){const years=[...new Set(ROUNDS.map(r=>r.date.slice(0,4)))];return `<section class="round-catalog" aria-label="연도별 회차 선택"><p class="round-guide">회차를 선택한 뒤 <strong>문항별 해설</strong> 또는 <strong>한 번에 채점</strong>을 고르세요.</p>${years.map(year=>`<section class="round-year"><h2>${year}년</h2><div class="round-grid">${ROUNDS.filter(r=>r.date.startsWith(year)).map(roundCard).join('')}</div></section>`).join('')}</section>`;}
function practicePage(){return `${pageHead('회차별 기출 주제 풀기',`${roundRange()} · 회차마다 50문제 · 총 ${QUESTIONS.length}문제`)}${roundCatalog()}<details class="practice-question-list" ${filter!=='all'||subjectFilter||search?'open':''}><summary>문항 목록·검색 <span>${QUESTIONS.length}문제</span></summary><label class="round-filter" for="round-filter"><strong>회차 선택</strong><select id="round-filter" aria-label="회차 선택"><option value="all" ${filter==='all'?'selected':''}>전체 회차 · ${QUESTIONS.length}문제</option>${ROUNDS.map(r=>`<option value="${r.number}" ${filter===String(r.number)?'selected':''}>${r.number}회 · ${QUESTIONS.filter(q=>q.round===r.number).length}문제</option>`).join('')}</select></label>${subjectChips()}<label class="search">${icon('search',18)}<input id="search" type="search" placeholder="개념이나 문제를 검색하세요" aria-label="문제 검색" value="${esc(search)}"></label><div class="section-head mt"><span class="subtle" id="list-count"></span><button class="text-btn" data-action="filtered-start">풀이 시작 ${icon('arrow',14)}</button></div><div id="bank-list" class="bank-list">${bankItems()}</div></details><p class="note">각 회차는 1·2·3과목 10·10·30문제입니다. 공개 자료의 주제 재구성 340문제에 출제 범위 보충 210문제를 더했습니다. 보충 문제는 별도 표시하며, 실제 시험 50문항 전체의 복원본은 아닙니다.</p>`;}
function subjectChips(){return `<div class="chips" role="group" aria-label="과목 필터">${['모든 과목',...SUBJECTS].map((t,i)=>`<button class="chip ${subjectFilter===i?'active':''}" data-action="filter-subject" data-subject="${i}">${i?`${i}과목`:'모든 과목'}</button>`).join('')}</div>`;}
function filteredQuestions(){return QUESTIONS.filter(q=>(view==='review'?(reviewFilter==='wrong'?state.attempts[q.id]&&!state.attempts[q.id].lastCorrect:state.bookmarks.includes(q.id)):(filter==='all'||q.round===Number(filter)))&&(!subjectFilter||q.subject===subjectFilter)&&(!search||(q.text+' '+q.topic).toLowerCase().includes(search.toLowerCase())));}
function bankItems(){const qs=filteredQuestions();if(!qs.length)return `<div class="empty" style="grid-column:1/-1">${icon(view==='review'?'bookmark':'search',35)}<h3>${search?'검색 결과가 없어요':view==='review'&&reviewFilter==='wrong'?'남아 있는 오답이 없어요':view==='review'?'저장한 북마크가 없어요':'해당하는 문제가 없어요'}</h3><p>${view==='review'?'틀린 문제와 저장한 문제를 여기서 다시 만날 수 있어요.':'다른 개념이나 필터로 찾아보세요.'}</p><button class="secondary" data-action="quick">10문제 풀러 가기 ${icon('arrow',16)}</button></div>`;return qs.map(q=>`<article class="bank-item"><div class="bank-top"><span class="badge neutral">${q.round}회 ${q.supplement?'보충':'주제'}</span><small>${q.subject}과목 · ${esc(q.topic)}</small>${bookmarkBtn(q)}</div><button style="text-align:left;padding:0" data-action="single" data-id="${q.id}"><p>${esc(q.text)}</p></button><small>${state.attempts[q.id]?`${state.attempts[q.id].lastCorrect?'최근 정답':'최근 오답'} · ${state.attempts[q.id].seen}회 풀이`:'아직 풀지 않은 문제'}</small></article>`).join('');}
function renderBankList(){const el=$('#bank-list');if(el){el.innerHTML=bankItems();$('#list-count').textContent=`${filteredQuestions().length}문제`;}}
function reviewPage(){const s=stats(state);return `${pageHead('한 번 더, 내 것으로.','헷갈렸던 문제를 다시 풀며 빈틈을 채워요.')}<div class="chips"><button class="chip ${reviewFilter==='wrong'?'active':''}" data-action="filter-review" data-filter="wrong">오답 ${s.wrong}</button><button class="chip ${reviewFilter==='bookmarks'?'active':''}" data-action="filter-review" data-filter="bookmarks">북마크 ${state.bookmarks.length}</button></div>${subjectChips()}<label class="search">${icon('search',18)}<input id="search" type="search" aria-label="복습 문제 검색" placeholder="복습할 개념 찾기" value="${esc(search)}"></label><div class="section-head mt"><span class="subtle" id="list-count">${filteredQuestions().length}문제</span><button class="text-btn" data-action="filtered-start">모아서 복습 ${icon('arrow',14)}</button></div><div id="bank-list" class="bank-list">${bankItems()}</div><p class="note">다시 풀어 맞힌 문제는 오답 목록에서 빠집니다. 북마크는 직접 해제할 때까지 유지됩니다.</p>`;}
function progressPage(){const s=stats(state);return `${pageHead('차곡차곡 쌓인 나의 기록','오늘의 풀이가 내일의 자신감이 됩니다.')}<div class="panel"><h3>과목별 누적 정답률</h3><div class="accuracy-bars">${SUBJECTS.map((t,i)=>{const as=QUESTIONS.filter(q=>q.subject===i+1).map(q=>state.attempts[q.id]).filter(Boolean),count=as.reduce((sum,a)=>sum+a.seen,0),right=as.reduce((sum,a)=>sum+a.correct,0),rate=count?Math.round(right/count*100):0;return `<div class="accuracy-bar"><div class="label"><span>${i+1}과목 · ${t}</span><strong>${count?rate+'%':'시작 전'}</strong></div><div class="progress-line"><span style="width:${rate}%"></span></div><small class="subtle">${right}/${count}회 정답 · ${as.length}개 문제 학습</small></div>`;}).join('')}</div><p class="mt" style="margin-bottom:0">총 ${s.answered}회 풀이 · 서로 다른 ${s.unique}개 문제 학습</p></div><div class="panel"><h3>최근 학습 이력</h3>${state.history.length?state.history.slice(0,20).map((r,i)=>`<button class="history-row full" data-action="history" data-index="${i}" style="text-align:left"><div>${esc(r.title)}<small>${new Date(r.endedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})} · ${modeLabel(r.mode)} · ${r.correct}/${r.total} 정답</small></div><strong>${r.score}<small>${r.mode==='exam'?'점':'%'}</small></strong>${icon('chevron',16)}</button>`).join(''):'<p>풀이를 완료하면 점수와 과목별 결과가 여기에 남아요.</p>'}</div>`;}
function settingsPage(){return `${pageHead('나에게 맞는 학습실','설치하고, 백업하고, 편하게 읽으세요.')}<section class="panel"><h3>학습 설정</h3><div class="settings-row"><label for="exam-date">나의 시험 날짜</label><input id="exam-date" type="date" value="${state.examDate}" min="2020-01-01" max="2100-12-31"></div><p>기본 날짜는 51회 예정일 2026.10.31입니다. 응시일에 맞게 바꿀 수 있어요.</p><div class="settings-row"><label for="font-size">문제 글자 크기</label><select id="font-size"><option value="normal" ${state.fontSize==='normal'?'selected':''}>기본</option><option value="large" ${state.fontSize==='large'?'selected':''}>크게</option></select></div></section><section class="panel"><h3>앱 설치 · 오프라인</h3><p>홈 화면에 설치하면 앱처럼 열 수 있어요. 문제·보기·해설을 이 기기에 저장해 인터넷 없이도 풀 수 있습니다.</p><div class="offline-label">${offlineReady?`✓ 문제 ${QUESTIONS.length}개와 앱 파일이 오프라인 저장되었습니다.`:'오프라인 파일 준비 중 · 첫 접속은 인터넷이 필요합니다.'}</div><button class="primary mt" data-action="install">${icon('download',18)} 설치 방법 보기</button>${swRegistration?.waiting?'<button class="secondary mt" data-action="update">새 버전으로 업데이트</button>':''}</section><section class="panel"><h3>나의 학습 기록</h3><p>과목별 정답률과 최근 풀이 결과를 확인해 보세요.</p><button class="secondary" data-action="navigate" data-view="progress">내 기록 보기</button></section><section class="panel"><h3>나의 기록 백업</h3><p>기록은 이 브라우저에만 저장됩니다. 다른 휴대폰으로 옮기거나 브라우저 데이터를 지우기 전에 백업해 주세요.</p><div class="settings-actions"><button class="secondary" data-action="export">${icon('download',17)} 백업 내려받기</button><button class="secondary" data-action="import">백업 불러오기</button><input class="hidden-input" id="backup-input" type="file" accept="application/json,.json"></div></section><section class="panel"><h3>문항 안내 · 출처</h3><p>2026.10.12 기준, ${roundRange()} 각 50문제, 총 ${QUESTIONS.length}문제입니다. 공개 자료의 주제 재구성 340문제와 출제 범위 기반 보충 210문제로 구성합니다. 보충은 해당 회차의 실제 출제 확인 자료가 아닙니다. 실제 원문·정답을 그대로 복원한 자료는 아닙니다. 공식 시험과 무관한 개인 학습 도구이며 이지패스의 디자인·문제·브랜드 자산을 사용하지 않았습니다.</p><button class="secondary" data-action="sources">출처와 작성 기준 확인</button></section><section class="panel"><h3>학습 기록 초기화</h3><p>진도, 오답, 북마크, 진행 중인 풀이와 학습 이력을 모두 지웁니다.</p><button class="danger" data-action="reset-intro">기록 초기화</button></section>`;}
let studySubject=1,studyMode='concept',studyReading='easy',studyCategory='all',studySearch='';
const studyOpen=new Set([STUDY_CARDS[0].id]);
function studyFiltered(){
  const needle=studySearch.trim().toLocaleLowerCase('ko-KR');
  const source=studyMode==='memory'?STUDY_CARDS:SUMMARY_NOTES;
  return source.filter(c=>c.subject===studySubject&&(studyCategory==='all'||studyUnit(c)===studyCategory)&&(!needle||JSON.stringify([c.title,c.lead,c.summary,c.points,c.rows,c.steps,c.memory,c.tip,c.caution,c.pitfall,c.recall,c.formulas,c.compare,c.example,c.deep,c.code,studyMode==='concept'?EASY_NOTES[c.id]:null,studyMode==='concept'?NOTE_ILLUSTRATIONS[c.id]:null]).toLocaleLowerCase('ko-KR').includes(needle)));
}
function studyUnit(c){return studyMode==='memory'?c.category:NOTE_CHAPTERS[c.subject][c.chapter];}
function noteSection(n){
  return `<section class="note-section" id="note-${n.id}"><h3 tabindex="-1">${esc(n.title)}</h3>${studyReading==='easy'?renderEasyNote(n.id):''}<details class="note-exam-detail" ${studyReading==='exam'?'open':''}><summary>시험 핵심 보기<span>표·절차·공식</span></summary><div class="note-exam-body"><p class="note-lead">${esc(n.lead)}</p>
    ${n.rows.length?`<table class="note-table"><caption class="sr-only">${esc(n.title)} 핵심 정리</caption><thead class="sr-only"><tr><th scope="col">구분</th><th scope="col">핵심 내용</th></tr></thead><tbody>${n.rows.map(([term,text])=>`<tr><th scope="row">${esc(term)}</th><td>${esc(text)}</td></tr>`).join('')}</tbody></table>`:''}
    ${n.steps.length?`<ol class="note-steps">${n.steps.map(([title,text])=>`<li><strong>${esc(title)}</strong><span>${esc(text)}</span></li>`).join('')}</ol>`:''}
    ${n.points.length?`<ul class="note-points">${n.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}
    ${n.formulas.length?`<div class="note-formulas" aria-label="핵심 공식"><h4>꼭 기억할 공식</h4>${n.formulas.map(f=>`<p>${esc(f)}</p>`).join('')}</div>`:''}
    ${n.tip?`<p class="note-tip"><strong>암기</strong> ${esc(n.tip)}</p>`:''}
    ${n.caution?`<p class="note-caution"><strong>주의</strong> ${esc(n.caution)}</p>`:''}
  </div></details>${n.deep.length?`<section class="note-depth" aria-labelledby="depth-${n.id}"><h4 id="depth-${n.id}">꼼꼼히 이해하기</h4>${n.deep.map(([title,text])=>`<div><h5>${esc(title)}</h5><p>${esc(text)}</p></div>`).join('')}</section>`:''}${n.code?`<section class="note-code" aria-labelledby="code-${n.id}"><h4 id="code-${n.id}">R 코드로 확인</h4><pre><code translate="no">${esc(n.code.text)}</code></pre><div class="note-code-result"><strong>실행 결과</strong><pre><samp translate="no">${esc(n.code.result)}</samp></pre></div></section>`:''}<section class="note-example" aria-labelledby="example-${n.id}"><h4 id="example-${n.id}">예제로 확인</h4><p>${esc(n.example.question)}</p><details class="note-solution" ${studyReading==='exam'?'open':''}><summary>풀이 보기</summary><ol>${n.example.solution.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details></section></section>`;
}
function summaryDocument(notes){
  const chapters=NOTE_CHAPTERS[studySubject];
  return `<article class="summary-document" data-subject="${studySubject}" aria-label="${studySubject}과목 요약노트"><header class="note-cover"><h2 tabindex="-1">${studySubject}과목 · ${SUBJECTS[studySubject-1]}</h2><p>${studyReading==='easy'?'그림 → 개념 이해 → 예제와 풀이':'정의 · 비교 · 공식 · 상세 설명 · 예제와 풀이'}</p><ul class="note-color-key" aria-label="내용별 표시"><li class="key-concept">그림·개념</li><li class="key-depth">상세 설명</li><li class="key-formula">공식</li><li class="key-example">예제·풀이</li><li class="key-caution">주의점</li></ul></header>${chapters.map((title,i)=>{
    const items=notes.filter(n=>n.chapter===i);if(!items.length)return '';
    return `<section class="note-chapter"><header class="note-chapter-head"><h2>${esc(title)}</h2><p>${esc(CHAPTER_GUIDES[studySubject][i][0])}</p><p class="note-chapter-focus"><strong>공부할 때</strong> ${esc(CHAPTER_GUIDES[studySubject][i][1])}</p></header>${items.map(noteSection).join('')}</section>`;
  }).join('')}<details class="note-references"><summary>이 과목의 참고 자료</summary><ul>${[...new Set(notes.flatMap(n=>n.sourceKeys))].map(key=>`<li><a href="${STUDY_SOURCES[key].url}" target="_blank" rel="noopener noreferrer">${esc(STUDY_SOURCES[key].title)} ↗</a></li>`).join('')}</ul></details></article>`;
}
function studyTable(c){return c.compare?`<div class="study-table-wrap"><table class="study-table"><caption>${esc(c.title)} 비교</caption><thead><tr>${c.compare.headers.map(t=>`<th scope="col">${esc(t)}</th>`).join('')}</tr></thead><tbody>${c.compare.rows.map(row=>`<tr>${row.map((t,i)=>i?`<td>${esc(t)}</td>`:`<th scope="row">${esc(t)}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';}
function studyItem(c){
  const memory=studyMode==='memory';
  return `<details class="study-card" id="study-${c.id}" data-study-id="${c.id}" ${studyOpen.has(c.id)?'open':''}>
    <summary><span><small class="study-category">${esc(c.category)}</small><strong>${esc(c.title)}</strong><span class="study-preview">${esc(memory?c.memory.hook:c.summary)}</span></span><span class="study-chevron">${icon('chevron',18)}</span></summary>
    <div class="study-body">
      ${memory?`<section class="study-memory"><h3>기억 문구</h3><strong>${esc(c.memory.hook)}</strong><p>${esc(c.memory.text)}</p></section>`:`<section><h3>핵심 개념</h3><ul class="study-points">${c.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></section>${c.formulas?`<section class="study-formulas"><h3>꼭 기억할 공식</h3>${c.formulas.map(f=>`<p>${esc(f)}</p>`).join('')}</section>`:''}${studyTable(c)}<section class="study-memory"><h3>암기 팁</h3><strong>${esc(c.memory.hook)}</strong><p>${esc(c.memory.text)}</p></section>`}
      <section class="study-pitfall"><h3>헷갈림 주의</h3><p>${esc(c.pitfall)}</p></section>
      <section class="study-recall"><h3>스스로 확인</h3><p>${esc(c.recall.prompt)}</p><details class="study-answer"><summary>정답 보기</summary><p>${esc(c.recall.answer)}</p></details></section>
      ${memory?`<button class="secondary study-concept-link" data-action="study-concept" data-id="${c.id}">관련 개념 보기 ${icon('book',16)}</button>`:''}
      <details class="study-source"><summary>참고 자료</summary><ul>${c.sourceKeys.map(key=>`<li><a href="${STUDY_SOURCES[key].url}" target="_blank" rel="noopener noreferrer">${esc(STUDY_SOURCES[key].title)} ↗</a></li>`).join('')}</ul></details>
    </div>
  </details>`;
}
function studyItems(){const items=studyFiltered();return items.length?(studyMode==='memory'?items.map(studyItem).join(''):summaryDocument(items)):`<div class="study-empty"><h3>이 과목에서 찾은 항목이 없어요.</h3><p>다른 단원을 선택하거나 더 짧은 개념 이름으로 검색해 주세요.</p><button class="secondary" data-action="study-clear">검색·단원 초기화</button></div>`;}
function studyAllOpen(){const cards=studyFiltered();return cards.length>0&&cards.every(c=>studyOpen.has(c.id));}
function studyCountLabel(){return `${studyFiltered().length}개 항목${studyCategory==='all'?'':` · ${studyCategory}`}${studySearch.trim()?` · “${studySearch.trim()}” 검색`:''}`;}
function renderStudyList(){const list=$('#study-list');if(!list)return;list.innerHTML=studyItems();$('#study-count').textContent=studyCountLabel();const expand=$('#study-expand');if(expand){expand.textContent=studyAllOpen()?'모두 접기':'모두 펼치기';expand.disabled=studyFiltered().length===0;}$('#study-clear-filter').hidden=studyCategory==='all'&&!studySearch.trim();$('#study-print')?.toggleAttribute('disabled',studyFiltered().length===0);}
function conceptPage(){
  const memory=studyMode==='memory',source=memory?STUDY_CARDS:SUMMARY_NOTES,categories=memory?[...new Set(source.filter(c=>c.subject===studySubject).map(c=>c.category))]:NOTE_CHAPTERS[studySubject];
  return `<div class="study-room ${memory?'memory-room':'notes-room'}">${pageHead('핵심 요약노트','그림으로 이해하고, 세부 개념과 예제 풀이로 꼼꼼히 복습해요.')}
    <div class="study-subjects" role="group" aria-label="공부할 과목">${SUBJECTS.map((title,i)=>`<button data-action="study-subject" data-subject="${i+1}" aria-label="${i+1}과목 ${title}" aria-pressed="${studySubject===i+1}"><strong>${i+1}과목</strong><span>${source.filter(c=>c.subject===i+1).length}개 항목</span></button>`).join('')}</div>
    <div class="study-modes" role="group" aria-label="정리 방식"><button data-action="study-mode" data-mode="concept" aria-pressed="${!memory}">요약노트</button><button data-action="study-mode" data-mode="memory" aria-pressed="${memory}">암기 비법</button></div>
    ${!memory?`<div class="note-reading" role="group" aria-label="요약노트 읽기 방식"><button data-action="study-reading" data-reading="easy" aria-pressed="${studyReading==='easy'}">그림으로 이해</button><button data-action="study-reading" data-reading="exam" aria-pressed="${studyReading==='exam'}">시험 요약</button></div>`:''}
    <details class="note-tools" ${studyCategory!=='all'||studySearch.trim()?'open':''}><summary>목차·검색 <span>${categories.length}개 단원</span></summary><div class="study-filters"><label class="study-unit">단원<select id="study-unit" name="study-unit"><option value="all">모든 단원</option>${categories.map(t=>`<option value="${esc(t)}" ${studyCategory===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="study-search-label" for="study-search">현재 과목에서 검색<span class="search">${icon('search',18)}<input id="study-search" name="study-search" type="search" maxlength="120" autocomplete="off" placeholder="예: ${['DIKW, 데이터베이스','CRISP-DM, 조직','회귀, 재현율'][studySubject-1]}…" value="${esc(studySearch)}"></span></label></div><div class="note-toc" role="group" aria-label="단원 바로 보기">${categories.map(t=>`<button data-action="note-unit" data-unit="${esc(t)}">${esc(t)}</button>`).join('')}</div></details>
    ${studyMode==='memory'?'<p class="study-instruction">기억 문구를 본 뒤, ‘스스로 확인’의 답을 먼저 떠올리고 정답을 펼쳐 보세요.</p>':''}
    <div class="study-list-tools"><span id="study-count" role="status" aria-live="polite">${esc(studyCountLabel())}</span>${memory?`<button class="text-btn" id="study-expand" data-action="study-expand" ${studyFiltered().length?'':'disabled'}>${studyAllOpen()?'모두 접기':'모두 펼치기'}</button>`:`<button class="text-btn" id="study-print" data-action="study-print" ${studyFiltered().length?'':'disabled'}>인쇄·PDF</button>`}</div><button class="text-btn note-clear" id="study-clear-filter" data-action="study-clear" ${studyCategory==='all'&&!studySearch.trim()?'hidden':''}>검색·단원 초기화</button>
    <div id="study-list" class="study-list">${studyItems()}</div>
    <section class="study-practice"><h2>문제로 기억을 확인해요.</h2><p>이 과목의 문제를 풀며 방금 읽은 개념을 적용해 보세요.</p><button class="primary" data-action="study-practice">${studySubject}과목 문제 풀기 ${icon('arrow',17)}</button></section>
    <p class="note">핵심 개념과 암기 문구는 자체 작성했습니다. <a href="${STUDY_SOURCES.dataq.url}" target="_blank" rel="noopener noreferrer">공식 출제 범위 ↗</a></p>
  </div>`;
}
function quizPage(){
  const s=state.active;if(!s)return homePage();
  const q=BY_ID.get(s.ids[s.index]),selected=s.answers[q.id],deferred=isDeferredMode(s.mode),checked=!deferred&&!!s.checked[q.id],isExam=s.mode==='exam',answered=Object.keys(s.answers).length;
  return `<div class="quiz-shell"><div class="quiz-toolbar"><button class="icon-btn" data-action="pause" aria-label="저장하고 학습 홈으로">${icon('back')}</button><h2>${esc(s.title)}</h2>${isExam?`<span class="timer" id="timer">${icon('clock',16)}<span></span></span>`:'<span class="subtle">자동 저장</span>'}<button class="icon-btn" data-action="navigator" aria-label="문제 번호로 이동">${icon('grid',19)}</button></div><div class="section-head"><span class="subtle"><strong>${String(s.index+1).padStart(2,'0')}</strong> / ${s.ids.length}</span><span class="subtle">${deferred?`${answered}문제 응답 · ${modeLabel(s.mode)}`:`${q.subject}과목 · 문항별 해설`}</span></div><div class="quiz-progress"><span style="width:${(s.index+1)/s.ids.length*100}%"></span></div><article class="question-card"><div class="qmeta"><span class="badge">${q.round}회 ${q.supplement?'보충':'주제'}</span><span>${esc(q.topic)}</span>${bookmarkBtn(q)}</div><h1 class="question-text" style="font-size:var(--q-size)">${esc(q.text)}</h1>${q.given?`<div class="question-given">${esc(q.given)}</div>`:''}<div class="options" role="group" aria-label="답안 선택">${q.options.map((o,i)=>`<button class="option ${selected===i?'selected':''} ${checked&&i===q.answer?'correct':''} ${checked&&selected===i&&selected!==q.answer?'wrong':''}" data-action="answer" data-answer="${i}" aria-pressed="${selected===i}" ${checked?'disabled':''}><span class="option-num">${i+1}</span><span>${esc(o)}</span>${checked&&i===q.answer?`<span class="option-state">${icon('check',16)}</span>`:''}</button>`).join('')}</div>${checked?feedback(q,selected):''}</article><div class="quiz-actions"><button class="secondary" data-action="prev" ${s.index===0?'disabled':''}>${icon('back',17)} 이전</button>${deferred?`<button class="primary" data-action="${s.index===s.ids.length-1?'finish-intro':'next'}">${s.index===s.ids.length-1?'답안 제출':'다음 문제'} ${icon('arrow',17)}</button>`:checked?`<button class="primary" data-action="${s.index===s.ids.length-1?'finish':'next'}">${s.index===s.ids.length-1?'학습 결과 보기':'다음 문제'} ${icon('arrow',17)}</button>`:`<button class="primary" data-action="check" ${selected===undefined?'disabled':''}>정답 확인 ${icon('check',17)}</button>`}</div><p class="quiz-footnote">${deferred?'제출하면 정답과 해설이 공개됩니다. 미응답은 오답으로 처리합니다.':'답을 고른 뒤 정답 확인을 누르면 해설이 바로 표시됩니다.'}</p>${deferred&&s.index<s.ids.length-1?`<button class="text-btn quiz-submit" data-action="finish-intro">지금 답안 제출하기 ${icon('check',14)}</button>`:''}</div>`;
}
function feedback(q,selected){const correct=selected===q.answer;return `<section class="feedback ${correct?'':'incorrect'}" tabindex="-1"><h3>${icon(correct?'check':'refresh',18)} ${correct?'잘했어요, 정답입니다.':`정답은 ${q.answer+1}번이에요.`}</h3><p>${esc(q.explanation)}</p><small>${esc(q.kind)} · 실제 시험 원문과 다릅니다.</small><a href="${SOURCES[q.source].url}" target="_blank" rel="noopener noreferrer">${q.supplement?'보충 출제 범위':'참고 출제 주제'} · ${esc(SOURCES[q.source].title)} ↗</a></section>`;}
function resultPage(){if(!result)return homePage();const r=result,isExam=r.mode==='exam';return `<div class="quiz-shell">${pageHead('풀이 완료. 오늘도 한 걸음!',esc(r.title))}<div class="result-card"><div class="eyebrow">${isExam?'90분 모의고사 결과':modeLabel(r.mode)+' 결과'}</div><div class="score">${r.score}<span>${isExam?'점':'% 정답'}</span></div><h2>${isExam?(r.passed?'합격 기준을 충족했어요!':'조금 더 채워볼까요?'):'오늘의 공부를 잘 마쳤어요.'}</h2><p>${r.correct} / ${r.total}문제 정답 · ${Math.ceil((Math.min(r.endedAt,r.deadline??r.endedAt)-r.startedAt)/60000)}분 풀이</p></div><div class="result-subjects">${r.subjects.map(p=>`<div><small>${p.subject}과목</small><strong class="${isExam&&p.percent<40?'fail':''}">${p.total?`${p.correct} / ${p.total}`:'—'}</strong><small>${p.total?(isExam?(p.percent<40?'과락':'과락 없음'):`정답률 ${p.percent}%`):'출제 없음'}</small></div>`).join('')}</div><p class="note">${isExam?'합격 기준: 총점 60점 이상 + 각 과목 40% 이상. 이 결과는 재구성 문제의 학습 참고 지표입니다.':'오답은 자동으로 저장됩니다. 다시 풀어 맞히면 오답 목록에서 빠져요.'}</p><div class="settings-actions mt"><button class="primary" data-action="result-wrong">${icon('refresh',17)} 이번 오답 다시 풀기</button><button class="secondary" data-action="navigate" data-view="home">학습 홈</button></div><div class="section-head mt"><h2>문제별 결과 · 해설</h2></div><div class="result-review">${r.ids.map((id,i)=>{const q=BY_ID.get(id),ok=r.answers[id]===q.answer;return `<button data-action="result-detail" data-id="${id}"><span class="${ok?'positive':'red'}">${ok?'✓':'↻'}</span>${i+1}. ${esc(q.topic)} <small class="subtle">${ok?'정답':r.answers[id]===undefined?'미응답':'오답'}</small></button>`;}).join('')}</div></div>`;}
function start(qs,mode,title){if(!qs.length){toast('현재 선택한 범위에 문제가 없습니다.');return;}if(state.active){pendingStart={qs,mode,title};confirmDialog('진행 중인 풀이가 있어요','새 풀이를 시작하면 진행 중인 답안은 종료됩니다. 이미 확인한 학습 기록은 유지됩니다.','replace-session','새 풀이 시작');return;}state.active=createSession(qs,mode,title);save();go('quiz');}
let pendingStart=null,pendingImport=null,practiceDraft=null;
function chooseMode(qs,title,mock=false){
  if(!qs.length){toast('현재 선택한 범위에 문제가 없습니다.');return;}
  practiceDraft={qs,title,mock};
  const batch=state.preferredMode==='batch',supplements=qs.filter(q=>q.supplement).length;
  dialog('풀이 방식 선택',`<p class="mode-summary"><strong>${esc(title)}</strong><br>${qs.length}문제 · ${[1,2,3].map(n=>`${n}과목 ${qs.filter(q=>q.subject===n).length}`).join(' / ')}<small>주제 재구성 ${qs.length-supplements} · 출제 범위 보충 ${supplements}</small></p>
    <fieldset class="mode-picker"><legend>어떻게 풀까요?</legend>
      <label class="mode-choice"><input type="radio" name="study-mode" value="learn" ${!batch?'checked':''}><span><strong>문항별 해설 보기</strong><small>한 문제를 풀고 정답 확인을 누르면 바로 해설을 볼 수 있어요.</small></span></label>
      <label class="mode-choice"><input type="radio" name="study-mode" value="batch" ${batch?'checked':''}><span><strong>한 번에 채점하기</strong><small>풀이 중에는 답을 자유롭게 바꾸고, 제출한 뒤 점수와 해설을 확인해요.</small></span></label>
    </fieldset>
    ${mock?`<label class="timer-choice"><input id="timed-exam" type="checkbox" checked ${!batch?'disabled':''}><span><strong>90분 제한 시간 사용</strong><small>한 번에 채점 모드에서 선택할 수 있어요. 시간이 끝나면 자동 제출돼요.</small></span></label><p class="dialog-source">${roundRange()}의 재구성 문제를 10 · 10 · 30개로 조합합니다. 시간 제한 사용 시 합격·과락 기준도 확인합니다.</p>`:'<p class="dialog-source">두 방식 모두 시간 제한 없이 풀며, 답안은 자동 저장됩니다.</p>'}`,
    '<button class="secondary" data-action="close-dialog">취소</button><button class="primary" data-action="mode-start">풀이 시작</button>');
}
function startSelectedMode(){
  if(!practiceDraft)return;
  const choice=$('input[name="study-mode"]:checked')?.value;
  if(!['learn','batch'].includes(choice))return;
  const draft=practiceDraft;
  const mode=choice==='batch'&&draft.mock&&$('#timed-exam')?.checked?'exam':choice;
  state.preferredMode=choice;save();practiceDraft=null;closeDialog();
  start(draft.qs,mode,draft.title);
}
function quick(){const pool=shuffled(QUESTIONS).sort((a,b)=>{const av=state.attempts[a.id],bv=state.attempts[b.id];return (av?av.lastCorrect?2:1:0)-(bv?bv.lastCorrect?2:1:0);});chooseMode(pool.slice(0,10),'오늘의 10문제');}
function showInstall(){if(window.matchMedia('(display-mode: standalone)').matches||navigator.standalone){toast('이미 앱으로 사용하고 있어요.');return;}dialog('내 폰에 ADsP 포켓 담기',`<p>휴대폰 브라우저에서 이 주소를 열고 홈 화면에 추가하세요.</p><h3>iPhone · iPad</h3><ol class="steps"><li>Safari에서 페이지를 열어요.</li><li>공유 버튼을 누른 뒤 <strong>홈 화면에 추가</strong>를 선택해요.</li><li>추가 후 홈 화면의 아이콘으로 실행해요.</li></ol><h3>Android</h3><ol class="steps"><li>Chrome에서 페이지를 열어요.</li><li>메뉴(⋮)에서 <strong>앱 설치</strong> 또는 <strong>홈 화면에 추가</strong>를 선택해요.</li></ol><p class="dialog-source">처음에는 온라인으로 한 번 열어 오프라인 준비 완료를 확인하세요. 출처 링크 방문은 인터넷이 필요합니다.</p>`,installPrompt?'<button class="primary" data-action="native-install">앱 설치하기</button>':'<button class="primary" data-action="close-dialog">확인했어요</button>');}
function showSources(){dialog('문항 안내 · 출처',`<p>${roundRange()} 각 50문제, 총 ${QUESTIONS.length}문제입니다. 공개 자료에서 확인한 주제 재구성 340문제와 출제 범위에 맞춘 자체 보충 210문제로 구성했습니다. 시험 원문·기존 문제집의 문장과 선택지를 옮기지 않았으며 공식 답안은 아닙니다. 보충 문제는 해당 회차의 실제 출제 확인 자료가 아닙니다.</p><p>${ROUNDS.map(r=>`${r.number}회 50문제(주제 ${QUESTIONS.filter(q=>q.round===r.number&&!q.supplement).length}+보충 ${QUESTIONS.filter(q=>q.round===r.number&&q.supplement).length})`).join(' · ')}<br>40~48회는 교육업체 공개 복원 분석, 49회는 공개 학습 정리, 50회는 응시 후기를 참고했습니다. 각 회차는 학습 내용 기준으로 10·10·30문제를 배치했습니다. 실제 시험 순서와 다르며, 49회는 주제 확인 신뢰도가 상대적으로 낮습니다.</p><div class="round-source-list">${ROUNDS.map(r=>{const keys=[...new Set(QUESTIONS.filter(q=>q.round===r.number).map(q=>q.source))];return `<details class="source-group"><summary>${r.number}회 · 출처 ${keys.length}개</summary><ul class="source-links">${keys.map(key=>{const source=SOURCES[key];return `<li><a href="${source.url}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a><small>${esc(source.note)}</small></li>`;}).join('')}</ul></details>`;}).join('')}</div><ul class="source-links"><li><a href="https://mobile.tomatopass.com/landing/License5139.do" target="_blank" rel="noopener noreferrer">2026 시험 일정 · 형식 확인 ↗</a><small>교육업체 일정 안내. 공식 일정은 DataQ에서 최종 확인하세요.</small></li><li><a href="https://www.dataq.or.kr/www/sub/a_06.do" target="_blank" rel="noopener noreferrer">공식 ADsP 자격 안내 · DataQ ↗</a></li></ul><p class="dialog-source">기준일: 2026.10.12 · 최신 완료 회차: 50회<br>개인 학습용 · 기기 안에서만 학습 기록 저장</p>`);}
function complete(){closeDialog();result=finishSession(state);save();go('result');}
function updateTimer(){if(!state.active||state.active.mode!=='exam')return;const seconds=remainingSeconds(state.active);if(seconds===0){result=finishSession(state);save();closeDialog();go('result');toast('90분이 지나 답안이 자동 제출되었습니다.');return;}const el=$('#timer');if(el){el.lastElementChild.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;el.classList.toggle('low',seconds<600);}}
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.action,s=state.active;
  if(['answer','check','next','prev','jump','finish-intro'].includes(a)&&s?.mode==='exam'&&remainingSeconds(s)===0){updateTimer();return;}
  switch(a){
    case 'navigate':go(b.dataset.view);break;
    case 'study-subject':studySubject=Number(b.dataset.subject);studyCategory='all';studySearch='';studyOpen.add(STUDY_CARDS.find(c=>c.subject===studySubject).id);render();$(`[data-action="study-subject"][data-subject="${studySubject}"]`)?.focus({preventScroll:true});break;
    case 'study-mode':studyMode=b.dataset.mode;studyCategory='all';studySearch='';render();$(`[data-action="study-mode"][data-mode="${studyMode}"]`)?.focus({preventScroll:true});break;
    case 'study-reading':studyReading=b.dataset.reading;renderStudyList();document.querySelectorAll('[data-action="study-reading"]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.reading===studyReading)));break;
    case 'study-clear':studyCategory='all';studySearch='';render();$('.note-tools').open=true;$('#study-search')?.focus({preventScroll:true});break;
    case 'note-unit':studyCategory=b.dataset.unit;$('#study-unit').value=studyCategory;renderStudyList();$('#study-list h2,#study-list .study-card>summary')?.focus({preventScroll:true});$('#study-list')?.scrollIntoView({block:'start'});break;
    case 'study-print':window.print();break;
    case 'study-expand':{const collapse=studyAllOpen();for(const c of studyFiltered()){if(collapse)studyOpen.delete(c.id);else studyOpen.add(c.id);}renderStudyList();$('#study-expand')?.focus({preventScroll:true});break;}
    case 'study-concept':studyMode='concept';studyCategory='all';studySearch='';render();$(`#note-${b.dataset.id}>h3`)?.focus({preventScroll:true});$(`#note-${b.dataset.id}`)?.scrollIntoView({block:'start'});break;
    case 'study-practice':chooseMode(shuffled(QUESTIONS.filter(q=>q.subject===studySubject)),`${studySubject}과목 · ${SUBJECTS[studySubject-1]} 개념 확인`);break;
    case 'close-dialog':closeDialog();break;
    case 'quick':quick();break;
    case 'round':chooseMode(QUESTIONS.filter(q=>q.round===Number(b.dataset.round)).sort((a,b)=>a.subject-b.subject),`${b.dataset.round}회 · 50문제 연습`);break;
    case 'subject':chooseMode(shuffled(QUESTIONS.filter(q=>q.subject===Number(b.dataset.subject))),`${b.dataset.subject}과목 · ${SUBJECTS[Number(b.dataset.subject)-1]}`);break;
    case 'resume':go('quiz');break;
    case 'pause':go('home');break;
    case 'replace-session':{const p=pendingStart;pendingStart=null;closeDialog();state.active=null;if(p)start(p.qs,p.mode,p.title);break;}
    case 'mode-start':startSelectedMode();break;
    case 'exam-intro':chooseMode(examQuestions(),'50문제 · 실전 모의고사',true);break;
    case 'filter-round':filter=b.dataset.filter;render();renderBankList();break;
    case 'filter-subject':subjectFilter=Number(b.dataset.subject);render();renderBankList();break;
    case 'filter-review':reviewFilter=b.dataset.filter;render();renderBankList();break;
    case 'filtered-start':chooseMode(filteredQuestions(),view==='review'?(reviewFilter==='wrong'?'오답 다시 풀기':'북마크 복습'):`${filter==='all'?'전체':filter+'회'} 출제 주제 연습`);break;
    case 'single':chooseMode([BY_ID.get(b.dataset.id)],BY_ID.get(b.dataset.id).topic+' · 1문제 연습');break;
    case 'bookmark':{const id=b.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();const y=window.scrollY;render();renderBankList();window.scrollTo(0,y);toast(state.bookmarks.includes(id)?'북마크에 저장했어요.':'북마크를 해제했어요.');break;}
    case 'answer':if(s&&!s.checked[s.ids[s.index]]){s.answers[s.ids[s.index]]=Number(b.dataset.answer);save();const y=scrollY;render();scrollTo(0,y);}break;
    case 'check':if(checkSessionAnswer(state)){save();render();const feedback=$('.feedback');feedback?.focus({preventScroll:true});feedback?.scrollIntoView({block:'nearest'});}break;
    case 'prev':if(s&&s.index>0){s.index--;save();render();scrollTo(0,0);}break;
    case 'next':if(s&&s.index<s.ids.length-1){s.index++;save();render();scrollTo(0,0);}break;
    case 'finish-intro':if(s){const missing=s.ids.length-Object.keys(s.answers).length;confirmDialog('답안을 제출할까요?',`${missing?`아직 ${missing}문제가 미응답입니다. 미응답은 오답으로 처리됩니다.<br>`:''}제출 후에는 정답과 해설을 확인할 수 있습니다.`,'finish','제출하고 채점');}break;
    case 'finish':complete();break;
    case 'navigator':if(s)dialog('문제 번호로 이동',`<p>파란색과 체크 표시는 응답한 문제입니다. 번호를 누르면 바로 이동해요.</p><div class="navigator">${s.ids.map((id,i)=>`<button class="${s.answers[id]!==undefined?'answered':''} ${i===s.index?'current':''}" data-action="jump" data-index="${i}" aria-label="${i+1}번 · ${s.answers[id]!==undefined?'응답 완료':'미응답'}">${i+1}${s.answers[id]!==undefined?' ✓':''}</button>`).join('')}</div>`);break;
    case 'jump':if(s){s.index=Number(b.dataset.index);save();closeDialog();render();scrollTo(0,0);}break;
    case 'result-wrong':if(result){const qs=result.ids.filter(id=>result.answers[id]!==BY_ID.get(id).answer).map(id=>BY_ID.get(id));if(qs.length)chooseMode(qs,'이번 풀이의 오답 복습');else toast('모두 맞혔어요. 복습할 오답이 없습니다.');}break;
    case 'result-detail':if(result){const q=BY_ID.get(b.dataset.id),selected=result.answers[q.id];dialog(`${q.subject}과목 · ${q.topic}`,`<p style="color:var(--ink)">${esc(q.text)}</p>${q.given?`<div class="question-given">${esc(q.given)}</div>`:''}<div class="options">${q.options.map((o,i)=>`<div class="option ${i===q.answer?'correct':''} ${i===selected&&selected!==q.answer?'wrong':''}"><span class="option-num">${i+1}</span><span>${esc(o)}</span></div>`).join('')}</div>${feedback(q,selected)}`);}break;
    case 'history':result=state.history[Number(b.dataset.index)];go('result');break;
    case 'sources':showSources();break;
    case 'install':showInstall();break;
    case 'native-install':if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;closeDialog();}break;
    case 'update':swRegistration?.waiting?.postMessage({type:'SKIP_WAITING'});break;
    case 'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`adsp-pocket-backup-${new Date().toISOString().slice(0,10)}.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('백업 파일을 내려받았습니다.');break;}
    case 'import':$('#backup-input')?.click();break;
    case 'confirm-import':if(pendingImport){state=pendingImport;pendingImport=null;save();closeDialog();go('settings');toast('백업에서 학습 기록을 불러왔어요.');}break;
    case 'reset-intro':confirmDialog('학습 기록을 초기화할까요?','진도·오답·북마크·진행 중인 풀이·학습 이력이 모두 삭제됩니다. 필요한 기록은 먼저 백업해 주세요.','reset','초기화');break;
    case 'reset':state=initialState();result=null;save();closeDialog();go('home');toast('학습 기록을 초기화했어요.');break;
  }
});
document.addEventListener('change',async e=>{
  if(e.target.id==='study-unit'){studyCategory=e.target.value;renderStudyList();}
  if(e.target.id==='round-filter'){filter=e.target.value;render();renderBankList();}
  if(e.target.name==='study-mode'){const timer=$('#timed-exam');if(timer)timer.disabled=e.target.value!=='batch';}
  if(e.target.id==='exam-date'){if(e.target.validity.valid&&e.target.value){state.examDate=e.target.value;save();toast('시험 날짜를 저장했어요.');}}
  if(e.target.id==='font-size'){state.fontSize=e.target.value;save();render();}
  if(e.target.id==='backup-input'){
    const file=e.target.files?.[0];if(!file)return;
    try{if(file.size>5_000_000)throw new Error('백업 파일은 5MB 이하여야 합니다.');pendingImport=validateState(JSON.parse(await file.text()));const s=stats(pendingImport);confirmDialog('백업을 불러올까요?',`${s.unique}개 문제의 학습 기록, 북마크 ${pendingImport.bookmarks.length}개를 확인했습니다.<br>현재 기록을 이 백업으로 교체합니다.`,'confirm-import','불러오기');}catch(err){pendingImport=null;toast(err.message==='Unexpected end of JSON input'?'파일이 올바르지 않습니다.':err instanceof SyntaxError?'ADsP 포켓 JSON 백업을 선택해 주세요.':err.message);}e.target.value='';
  }
});
document.addEventListener('toggle',e=>{const el=e.target;if(el.isConnected&&el.matches?.('.study-card')){if(el.open)studyOpen.add(el.dataset.studyId);else studyOpen.delete(el.dataset.studyId);const expand=$('#study-expand');if(expand)expand.textContent=studyAllOpen()?'모두 접기':'모두 펼치기';}},true);
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(views.includes(next)&&!(next==='quiz'&&!state.active)&&!(next==='result'&&!result)){view=next;render();renderBankList();}});
document.addEventListener('keydown',e=>{if(view!=='quiz'||$('#dialog').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(['1','2','3','4'].includes(e.key)){e.preventDefault();$(`[data-action="answer"][data-answer="${Number(e.key)-1}"]`)?.click();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateTimer();});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('appinstalled',()=>{installPrompt=null;closeDialog();toast('설치 완료! 홈 화면에서 열어 보세요.');});
async function setupOffline(){
  if(!('serviceWorker' in navigator))return;
  try{
    swRegistration=await navigator.serviceWorker.register('./sw.js',{scope:'./'});
    await navigator.serviceWorker.ready;
    const ready=await caches.match(new URL('./questions.js',location.href));offlineReady=!!ready;
    render();renderBankList();
    swRegistration.addEventListener('updatefound',()=>{const worker=swRegistration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('새 버전이 있어요. 설정에서 업데이트할 수 있습니다.');});});
  }catch{offlineReady=false;toast('오프라인 저장에 실패했습니다. 인터넷 연결 후 다시 열어 주세요.');}
}
let hadController=!!navigator.serviceWorker?.controller;
navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(hadController)location.reload();else hadController=true;});
render();renderBankList();setInterval(updateTimer,1000);setupOffline();
if(storageWarning)toast('기존 기록을 읽지 못했어요. 백업이 있다면 설정에서 불러와 주세요.');
